<script>
(function(){
const shell=document.getElementById('nexa-shell'),buttons=[...document.querySelectorAll('[data-group]')],panels=[...document.querySelectorAll('[data-panel]')];
function choose(key){buttons.forEach(b=>b.classList.toggle('active',b.dataset.group===key));panels.forEach(p=>p.hidden=p.dataset.panel!==key);}
buttons.forEach(b=>b.addEventListener('click',()=>{choose(b.dataset.group);shell.classList.remove('mobile-open');}));
document.getElementById('platform-menu')?.addEventListener('click',function(){this.setAttribute('aria-expanded',String(shell.classList.toggle('mobile-open')));});
const search=document.getElementById('platform-search');search?.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();if(!q){choose(document.querySelector('[data-group].active')?.dataset.group||'home');return;}panels.forEach(p=>{p.hidden=false;p.querySelectorAll('.platform-side-link').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(q));});});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search?.focus();}if(e.key==='Escape'){search?.blur();shell.classList.remove('mobile-open');}});
})();
</script>
